243	static void
244	proj_on_basis_c2p_phase_func(const double *xcomp, double *xphys, void *ctx)
245	{
246	  struct gk_proj_on_basis_c2p_func_ctx *c2p_ctx = ctx;
247	  int cdim = c2p_ctx->cdim; // Assumes update range is a phase range.
248	  gkyl_velocity_map_eval_c2p(c2p_ctx->vel_map, &xcomp[cdim], &xphys[cdim]);
249	}
250	
251	static void
252	gk_species_damping_project_phase_rate(
253	  const struct gkyl_gyrokinetic_app *app, const struct gk_species *gks, int num_quad,
254	  void (*rate_profile)(double t, const double *xn, double *fout, void *ctx), void *rate_profile_ctx,
255	  struct gkyl_array *rate_host, struct gkyl_array *rate
256	)
257	{
258	  struct gk_proj_on_basis_c2p_func_ctx proj_on_basis_c2p_ctx; // c2p function context.
259	  proj_on_basis_c2p_ctx.cdim = app->cdim;
260	  proj_on_basis_c2p_ctx.vdim = gks->local_vel.ndim;
261	  proj_on_basis_c2p_ctx.vel_map = gks->vel_map;
262	
263	  struct gkyl_basis basis_mult;
264	  gkyl_cart_modal_serendip(&basis_mult, gks->basis.ndim, 0);
265	
266	  gkyl_proj_on_basis *projup = gkyl_proj_on_basis_inew(&(struct gkyl_proj_on_basis_inp){
267	    .grid = &gks->grid,
268	    .basis = &basis_mult,
269	    .num_quad = num_quad,
270	    .num_ret_vals = 1,
271	    .eval = rate_profile,
272	    .ctx = rate_profile_ctx,
273	    .c2p_func = proj_on_basis_c2p_phase_func,
274	    .c2p_func_ctx = &proj_on_basis_c2p_ctx,
275	  });
276	  gkyl_proj_on_basis_advance(projup, 0.0, &gks->local, rate_host);
277	  gkyl_proj_on_basis_release(projup);
278	  gkyl_array_copy(rate, rate_host);
279	
280	  if (num_quad == 1) {
281	    gkyl_array_scale_range(rate, 1.0 / pow(sqrt(2.0), gks->grid.ndim), &gks->local);
282	  }
283	}
