288	gk_species_damping_advance_disabled(
289	  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_damping *damp,
290	  const struct gkyl_array *phi, const struct gkyl_array *fin, const struct gkyl_array *fbar_in,
