330	gk_species_damping_advance_low_pass_filter_same_basis(
331	  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_damping *damp,
332	  const struct gkyl_array *phi, const struct gkyl_array *fin, const struct gkyl_array *fbar_in,
333	  struct gkyl_array *f_buffer, struct gkyl_array *rhs, struct gkyl_array *cflrate
334	)
335	{
336	  // Compute f - fbar, where fbar uses the same basis as f.
337	  gkyl_array_set(f_buffer, 1.0, fin); // f_buffer = fin
338	  gkyl_array_accumulate(f_buffer, -1.0, fbar_in); // f_buffer = fin - fbar
339	  gkyl_array_scale_by_cell(f_buffer, damp->rate); // f_buffer = rate * (fin - fbar)
340	
341	  // Add damping term to RHS: df/dt -= rate * (f - fbar)
342	  // Add to the CFL frequency.
343	  gkyl_array_accumulate(rhs, -1.0, f_buffer);
344	  gkyl_array_accumulate(cflrate, 1.0, damp->rate);
345	}
