621	  }
622	
623	  if (!damp->type) {
624	    return;
625	  }
626	  gkyl_array_release(damp->rate);
627	  if (app->use_gpu) {
628	    gkyl_array_release(damp->rate_host);
629	  }
630	  if (damp->type == GKYL_GK_DAMPING_LOW_PASS_FILTER) {
631	    if (damp->fbar_mom_buffer) {
632	      gkyl_array_release(damp->fbar_mom_buffer);
633	    }
634	    gkyl_array_release(damp->fbar1);
635	    gkyl_array_release(damp->fbarnew);
636	    if (app->use_gpu && damp->write_fbar) {
637	      gkyl_array_release(damp->fbar_host);
638	    }
639	  }
