   312	gk_species_damping_advance_low_pass_filter_cellwise_const(
   313	  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_damping *damp,
   314	  const struct gkyl_array *phi, const struct gkyl_array *fin, const struct gkyl_array *fbar_in,
   315	  struct gkyl_array *f_buffer, struct gkyl_array *rhs, struct gkyl_array *cflrate
   316	)
   317	{
   318	  // Compute f - fbar, where fbar is stored as a cellwise-constant p0 field.
   319	  gkyl_array_set(f_buffer, 1.0, fin); // f_buffer = fin
   320	  gkyl_array_accumulate_offset(f_buffer, -1.0, fbar_in, 0); // f_buffer = fin - fbar
   321	  gkyl_array_scale_by_cell(f_buffer, damp->rate); // f_buffer = rate * (fin - fbar)
   322	
   323	  // Add damping term to RHS: df/dt -= rate * (f - fbar)
   324	  // Add to the CFL frequency.
   325	  gkyl_array_accumulate(rhs, -1.0, f_buffer);
   326	  gkyl_array_accumulate(cflrate, 1.0, damp->rate);
   327	}
