   348	gk_species_damping_advance(
   349	  gkyl_gyrokinetic_app *app, const struct gk_species *gks, struct gk_damping *damp,
   350	  const struct gkyl_array *phi, const struct gkyl_array *fin, const struct gkyl_array *fbar_in,
   351	  struct gkyl_array *f_buffer, struct gkyl_array *rhs, struct gkyl_array *cflrate
   352	)
