   498	// Damping object lifecycle.
   499	
   500	void
   501	gk_species_damping_init(
   502	  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_damping *damp
   503	)
   504	{
   505	  damp->type = gks->info.damping.type;
   506	  damp->evolve = false; // Whether the rate is time dependent.
   507	  damp->write_rate = gks->info.damping.write_rate;
   508	  damp->write_fbar = gks->info.damping.write_fbar;
   509	  damp->cellwise_const = gks->info.damping.cellwise_const;
   510	  damp->do_not_reset_fbar = gks->info.damping.do_not_reset_fbar;
   511	  const double rate_const = gks->info.damping.rate_const;
   512	
   513	  int num_quad = gks->info.damping.num_quad ? gks->info.damping.num_quad :
   514	                                              1; // Default is a p=0 mask.
   515	  assert(num_quad == 1); // MF 2025/06/11: Limited to this for now.
   516	
   517	  // Default function pointers.
   518	  damp->write_func = gk_species_damping_write_disabled;
   519	  damp->write_rate_func = gk_species_damping_write_rate_disabled;
   520	  damp->write_fbar_func = gk_species_damping_write_fbar_disabled;
   521	  damp->read_fbar_func = gk_species_damping_read_fbar_disabled;
   522	  damp->advance_func = gk_species_damping_advance_disabled;
   523	  damp->set_fbar_to_f_func = gk_species_damping_set_fbar_to_f_disabled;
   524	  damp->calc_fbar_rhs_func = gk_species_damping_calc_fbar_rhs_disabled;
   525	  damp->forward_euler_func = gk_species_damping_forward_euler_disabled;
   526	  damp->combine_func = gk_species_damping_combine_disabled;
   527	  damp->copy_func = gk_species_damping_copy_range_disabled;
   528	
   529	  // Default pointers for fbar arrays
   530	  damp->fbar = 0;
   531	  damp->fbar1 = 0;
   532	  damp->fbarnew = 0;
   533	  damp->fbar_host = 0;
   534	  damp->fbar_mom_buffer = 0;
   535	  damp->fbar_initialized = false;
   536	
   537	  if (!damp->type) {
   538	    return;
   539	  }
   540	
   541	  if (damp->write_rate) {
   542	    damp->write_rate_func = gk_species_damping_write_rate_enabled;
   543	  }
   544	
   545	  // Allocate rate array.
   546	  damp->rate = mkarr(app->use_gpu, 1, gks->local_ext.volume);
   547	  damp->rate_host = damp->rate;
   548	  if (app->use_gpu) {
   549	    damp->rate_host = mkarr(false, damp->rate->ncomp, damp->rate->size);
   550	  }
   551	
   552	  if (gks->info.damping.rate_profile) {
   553	    gk_species_damping_project_phase_rate(
   554	      app, gks, num_quad, gks->info.damping.rate_profile, gks->info.damping.rate_profile_ctx,
   555	      damp->rate_host, damp->rate
   556	    );
   557	    gkyl_array_scale(damp->rate, rate_const == 0.0 ? 1.0 : rate_const);
   558	  } else {
   559	    gkyl_array_clear(damp->rate, rate_const);
   560	  }
   561	
   562	  if (damp->type == GKYL_GK_DAMPING_USER_INPUT) {
   563	    // USER_INPUT supports either a projected profile, or a uniform constant if no profile is provided.
   564	    damp->advance_func = gk_species_damping_advance_user_input;
   565	  } else if (damp->type == GKYL_GK_DAMPING_LOW_PASS_FILTER) {
   566	    // LOW_PASS_FILTER supports either a projected phase-space profile or a uniform constant.
   567	    damp->evolve = true;
   568	
   569	    // Allocate filtered distribution function array in the requested basis.
   570	    int fbar_ncomp = damp->cellwise_const ? 1 : gks->basis.num_basis;
   571	    damp->fbar = mkarr(app->use_gpu, fbar_ncomp, gks->local_ext.volume);
   572	    damp->fbar1 = mkarr(app->use_gpu, fbar_ncomp, gks->local_ext.volume);
   573	    damp->fbarnew = mkarr(app->use_gpu, fbar_ncomp, gks->local_ext.volume);
   574	    damp->fbar_host = damp->fbar;
   575	    damp->fbar_initialized = true;
   576	    gkyl_array_clear(damp->fbar, 0.0);
   577	
   578	    if (gks->info.time_rate_diagnostics && !gks->info.is_static && damp->cellwise_const) {
   579	      damp->fbar_mom_buffer = mkarr(app->use_gpu, gks->basis.num_basis, gks->local_ext.volume);
   580	    }
   581	
   582	    if (damp->write_fbar) {
   583	      damp->read_fbar_func = gk_species_damping_read_fbar_enabled;
   584	      if (damp->cellwise_const) {
   585	        damp->write_fbar_func = gk_species_damping_write_fbar_cellwise_const;
   586	      } else {
   587	        damp->write_fbar_func = gk_species_damping_write_fbar_same_basis;
   588	      }
   589	      if (app->use_gpu) {
   590	        damp->fbar_host = mkarr(false, damp->fbar->ncomp, damp->fbar->size);
   591	      }
   592	    }
   593	
   594	    if (damp->cellwise_const) {
   595	      damp->advance_func = gk_species_damping_advance_low_pass_filter_cellwise_const;
   596	      damp->set_fbar_to_f_func = gk_species_damping_set_fbar_to_f_cellwise_const;
   597	      damp->calc_fbar_rhs_func = gk_species_damping_calc_fbar_rhs_cellwise_const;
   598	    } else {
   599	      damp->advance_func = gk_species_damping_advance_low_pass_filter_same_basis;
   600	      damp->set_fbar_to_f_func = gk_species_damping_set_fbar_to_f_same_basis;
   601	      damp->calc_fbar_rhs_func = gk_species_damping_calc_fbar_rhs_same_basis;
   602	    }
   603	    damp->forward_euler_func = gk_species_damping_forward_euler_enabled;
   604	    damp->combine_func = gk_species_damping_combine_enabled;
   605	    damp->copy_func = gk_species_damping_copy_range_enabled;
   606	  }
   607	
   608	  if (damp->evolve) {
   609	    damp->write_func = gk_species_damping_write_enabled;
   610	  } else {
   611	    damp->write_func = gk_species_damping_write_init_only;
   612	  }
   613	}
   614	
   615	void
   616	gk_species_damping_release(const struct gkyl_gyrokinetic_app *app, const struct gk_damping *damp)
   617	{
   618	  // Release remembered fbar state even when damping is currently disabled.
   619	  if (damp->fbar_initialized) {
   620	    gkyl_array_release(damp->fbar);
   621	  }
   622	
   623	  if (!damp->type) {
   624	    return;
   625	  }
   626	  gkyl_array_release(damp->rate);
   627	  if (app->use_gpu) {
   628	    gkyl_array_release(damp->rate_host);
   629	  }
   630	  if (damp->type == GKYL_GK_DAMPING_LOW_PASS_FILTER) {
   631	    if (damp->fbar_mom_buffer) {
   632	      gkyl_array_release(damp->fbar_mom_buffer);
   633	    }
   634	    gkyl_array_release(damp->fbar1);
   635	    gkyl_array_release(damp->fbarnew);
   636	    if (app->use_gpu && damp->write_fbar) {
   637	      gkyl_array_release(damp->fbar_host);
   638	    }
   639	  }
   640	}
   641	
   642	void
   643	gk_species_damping_reset(
   644	  gkyl_gyrokinetic_app *app, double tm, struct gk_species *gks, struct gk_damping *damp,
   645	  struct gkyl_gyrokinetic_damping damp_inp
   646	)
   647	{
   648	  bool has_fbar_backup = false;
   649	  struct gkyl_array *fbar_backup = 0;
   650	
   651	  // Create a reset-local backup if requested and there is restorable state.
   652	  if (damp_inp.do_not_reset_fbar) {
   653	    if (damp->fbar_initialized) {
   654	      has_fbar_backup = true;
   655	      fbar_backup = mkarr(app->use_gpu, damp->fbar->ncomp, damp->fbar->size);
   656	      gkyl_array_copy(fbar_backup, damp->fbar);
   657	    }
   658	  }
   659	
   660	  gk_species_damping_release(app, damp);
   661	
   662	  gks->info.damping = damp_inp;
   663	  gk_species_damping_init(app, gks, damp);
   664	
   665	  gk_species_damping_set_fbar_to_f(gks, damp, gks->f);
   666	
   667	  if (has_fbar_backup) {
   668	    if (damp->fbar_initialized) {
   669	      gkyl_array_copy(damp->fbar, fbar_backup);
   670	      gkyl_array_copy(damp->fbar1, fbar_backup);
   671	      gkyl_array_copy(damp->fbarnew, fbar_backup);
   672	    } else {
   673	      damp->fbar = gkyl_array_acquire(fbar_backup);
   674	      damp->fbar_initialized = true;
   675	    }
   676	    gkyl_array_release(fbar_backup);
   677	  }
   678	}
