static void
gk_species_moment_diag_jacobgeo_div_enabled_1st_comp(
  const struct gkyl_gyrokinetic_app *app, struct gk_species_moment *sm, struct gkyl_array *Jmom_in,
  struct gkyl_array *mom_out
)
